from pathlib import Path
with open(Path(__file__).with_name("questions.csv"), "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    w.writerow(["id", "question", "lang", "difficulty", "in_corpus", "ground_truth", "source_urls"])
    for i, (q, lang, diff, inc, gt, urls) in enumerate(Q, start=1):
        w.writerow([i, q, lang, diff, int(inc), gt, " | ".join(urls)])

import collections
